<?php
$receiptDetails=[
 'incoming'=>['title'=>'Envois à réceptionner','path'=>'butchery/receipts?status=incoming','action'=>'Ouvrir les réceptions','headers'=>['Référence / lot','Ferme','Poids (kg)','DLC','Transport'],'rows'=>[]],
 'pending'=>['title'=>'Contrôles sanitaires en attente','path'=>'butchery/receipts?status=pending','action'=>'Ouvrir les contrôles','headers'=>['Réception / envoi','Ferme','Poids (kg)','Arrivée','DLC'],'rows'=>[]],
];
foreach($incoming as$r)$receiptDetails['incoming']['rows'][]=[$r['transfer_number'].' · '.$r['batch_number'],$r['source_name'],$kg($r['quantity_kg']),date('d/m/Y',strtotime($r['expiry_date'])),$r['truck_plate'].' · '.$r['driver_name']];
foreach($pending as$r)$receiptDetails['pending']['rows'][]=[$r['receipt_number'].' · '.$r['transfer_number'],$r['source_name'],$kg($r['quantity_kg']),date('d/m/Y H:i',strtotime($r['received_at'])),date('d/m/Y',strtotime($r['expiry_date']))];
?>
<?php foreach($receiptDetails as$key=>$detail):?>
<section id="receipt-kpi-<?=e($key)?>" class="entity-modal workspace-entity-modal feed-editor butchery-overview-modal" role="dialog" aria-modal="true" aria-hidden="true" aria-labelledby="receipt-kpi-title-<?=e($key)?>"><header><div><p class="page-kicker">BOUCHERIE · DÉTAILS</p><h2 id="receipt-kpi-title-<?=e($key)?>"><?=e($detail['title'])?></h2></div><button type="button" class="modal-close" data-workspace-modal-close aria-label="Fermer les détails">×</button></header><div class="feed-form-body"><p class="butchery-home-note"><?=$key==='incoming'?'Envois expédiés par la ferme et dont l’arrivée reste à enregistrer.':'Réceptions arrivées à la boucherie, en attente de contrôle sanitaire avant leur entrée en chambre froide.'?></p><div class="table-responsive"><table class="enterprise-table" aria-label="<?=e($detail['title'])?>" data-search-placeholder="Rechercher dans ces détails"><thead><tr><?php foreach($detail['headers'] as$heading):?><th scope="col"><?=e($heading)?></th><?php endforeach;?></tr></thead><tbody><?php foreach($detail['rows'] as$line):?><tr><?php foreach($line as$value):?><td><?=e($value)?></td><?php endforeach;?></tr><?php endforeach;?><?php if(!$detail['rows']):?><tr><td colspan="<?=count($detail['headers'])?>">Aucun résultat pour cet indicateur.</td></tr><?php endif;?></tbody></table></div></div><footer><button type="button" class="btn-secondary" data-workspace-modal-close>Fermer</button><a class="btn-primary" href="<?=e(base_url($detail['path']))?>"><?=e($detail['action'])?></a></footer></section>
<?php endforeach;?>
